  "runningSeconds": 120,
  "scrollStable": true,
  "focusStable": true
}
### Ran Playwright code
```js
await page.evaluate('()=>{if(scrollY!==window.__working.y||document.activeElement.id!==window.__working.focused)throw Error(\'Working jump \'+JSON.stringify({before:window.__working,after:{y:scrollY,focused:document.activeElement.id}}));return {runningSeconds:120,scrollStable:true,focusStable:true};}');
```

